<template><MinipLayout title="我的评价" :canBack="true"><div class="list"><div v-for="r in list" :key="r.id" class="card"><div class="head"><div class="avatar">{{ (r.product || '?').charAt(0) }}</div><div class="main"><div class="product">{{ r.product }}</div><div class="stars">{{ '★'.repeat(r.rating || 5) }}{{ '☆'.repeat(5 - (r.rating || 5)) }}</div></div><span class="date">{{ r.date }}</span></div><div class="content">{{ r.content }}</div></div><div v-if="!list.length && !loading" class="empty">暂无评价</div></div></MinipLayout></template>
<script setup>import { ref, onMounted } from 'vue'; import api from '@/utils/api'
import { ElMessage } from 'element-plus'; import MinipLayout from './MinipLayout.vue'; const list = ref([]); onMounted(async () => { try { const r = await api.get('/mall/reviews?limit=50'); if (r.code === 0) list.value = r.data || [] } catch (e) {
    uni.showToast({ title: '加载失败,请稍后重试', icon: 'none' })
    list.value = []
  } }); </script>
<style scoped>.list { display: flex; flex-direction: column; gap: 8px; } .card { background: #fff; border-radius: 10px; padding: 12px; } .head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; } .avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, #fbbf24, #f59e0b); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; } .main { flex: 1; } .product { font-size: 13px; color: #1f2329; font-weight: 500; } .stars { font-size: 12px; color: #fbbf24; margin-top: 2px; letter-spacing: 1px; } .date { font-size: 10px; color: #9ca3af; } .content { font-size: 13px; color: #4b5563; line-height: 1.5; } .empty { text-align: center; padding: 40px 0; color: #9ca3af; font-size: 13px; }</style>